import { cn } from "@/registry/erbium/lib/erbium-utils";

import { Slider } from "@/registry/erbium/ui/slider";

type SliderProps = React.ComponentProps<typeof Slider>;

export const defaultProps = {} satisfies SliderProps;

export default function SliderExample({ className, ...props }: SliderProps = defaultProps) {
  return (
    <Slider
      defaultValue={[50]}
      max={100}
      step={1}
      className={cn("w-[60%]", className)}
      {...props}
    />
  );
}

import SliderExample from "../examples/slider-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <SliderExample />
  </div>
);

export default Example;
